/* Reel v3 render strip for scene "opening" (generated by reel-v3/make_scenes.py; plan reel-v3-plan.md §5).
 * Each segment is one shot: scene time runs linearly over it while the camera eases from one window of
 * the 1440×1000 scene to another, fitted to the shot's box (GRAPHIC 1080×1920, SPLIT the top 1080×1000).
 */
import { renderAt as renderScene } from './pilot.js';

const STRIP = {"fps": 30, "segments": [{"shot": 2, "f0": 0, "frames": 55, "reel": [2.25, 2.92], "box": [0, 0, 1080, 1920], "cam": [[720, 520, 520], [720, 500, 640]]}, {"shot": 3, "f0": 55, "frames": 38, "reel": [3.55, 4.33], "box": [0, 0, 1080, 1920], "cam": [[900, 470, 560], [930, 440, 500]]}, {"shot": 4, "f0": 93, "frames": 76, "reel": [4.4, 6.7], "box": [0, 0, 1080, 1000], "cam": [[660, 470, 920], [660, 480, 860]]}, {"shot": 6, "f0": 169, "frames": 61, "reel": [10.05, 11.3], "box": [0, 0, 1080, 1920], "cam": [[720, 420, 820], [720, 440, 760]]}, {"shot": 7, "f0": 230, "frames": 29, "reel": [11.3, 12.1], "box": [0, 0, 1080, 1920], "cam": [[720, 440, 760], [720, 450, 700]]}, {"shot": 12, "f0": 259, "frames": 74, "reel": [14.7, 16.6], "box": [0, 0, 1080, 1920], "cam": [[710, 470, 700], [710, 460, 600]]}, {"shot": 13, "f0": 333, "frames": 39, "reel": [16.6, 18.4], "box": [0, 0, 1080, 1920], "cam": [[420, 470, 700], [1020, 470, 700]]}, {"shot": 14, "f0": 372, "frames": 32, "reel": [18.6, 20.4], "box": [0, 0, 1080, 1000], "cam": [[760, 500, 1500], [760, 500, 1460]]}, {"shot": 15, "f0": 404, "frames": 21, "reel": [21.1, 22.1], "box": [0, 0, 1080, 1920], "cam": [[660, 460, 860], [640, 430, 740]]}, {"shot": 16, "f0": 425, "frames": 99, "reel": [22.2, 24.7], "box": [0, 0, 1080, 1000], "cam": ["fit", [720, 560, 1300]]}], "frames": 524, "native": false};
const gsap = window.gsap;
const EZ = gsap.parseEase('power2.inOut');
const lerp = (a, b, u) => a + (b - a) * u;
const cam = document.getElementById('reelcam');

const win = (c, box) => (c === 'fit' ? [720, 500, 1440] : c);
function renderFrame(f) {
  const seg = STRIP.segments.find((s) => f >= s.f0 && f < s.f0 + s.frames) ?? STRIP.segments.at(-1);
  const u = Math.min(1, Math.max(0, (f - seg.f0) / Math.max(1, seg.frames - 1)));
  renderScene(lerp(seg.reel[0], seg.reel[1], u));

  const [bx, by, bw, bh] = seg.box;
  const [c0, c1] = seg.cam ?? ['fit', 'fit'];
  const a = win(c0), b = win(c1), e = EZ(u);
  const cx = lerp(a[0], b[0], e), cy = lerp(a[1], b[1], e), w = lerp(a[2], b[2], e), s = bw / w;
  if (STRIP.native) return;
  cam.style.transform = `translate(${(bx + bw / 2 - cx * s).toFixed(2)}px, ${(by + bh / 2 - cy * s).toFixed(2)}px) scale(${s.toFixed(5)})`;
}
const clock = { f: 0 };
const N = STRIP.frames;
const tl = gsap.timeline({ paused: true });
tl.to(clock, { f: N, duration: N / 30, ease: 'none', onUpdate: () => renderFrame(Math.min(N - 1, Math.floor(clock.f + 1e-6))) }, 0);
renderFrame(0);
export const timeline = tl;
